module spanning_tree_checker(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [6:0] edge [0:31],\n    input wire [2:0] k,\n    output reg result,\n    output reg done\n);\n    \n    localparam [3:0] N = 4'd8;\n    localparam [5:0] M = 6'd32;\n    \n    localparam [2:0] IDLE         = 3'd0;\n    localparam [2:0] LOAD         = 3'd1;\n    localparam [2:0] RESET_PARENT = 3'd2;\n    localparam [2:0] PROCESS      = 3'd3;\n    localparam [2:0] NEXT_PASS    = 3'd4;\n    localparam [2:0] CHECK        = 3'd5;\n    localparam [2:0] DONE_STATE   = 3'd6;\n    \n    reg [2:0] state;\n    reg [2:0] min_blue, max_blue;\n    reg [2:0] current_blue;\n    reg phase;\n    reg [4:0] edge_idx;\n    reg weight_group;\n    reg [2:0] parent [0:7];  // Parent array for union-find\n    reg [0:31] color_reg;    // Color storage\n    reg [2:0] src_reg [0:31];// Source node storage\n    reg [2:0] dst_reg [0:31];// Destination node storage\n    \n    // Current edge components\n    wire current_color = color_reg[edge_idx];\n    wire [2:0] current_src = src_reg[edge_idx];\n    wire [2:0] current_dst = dst_reg[edge_idx];\n    \n    // Control signals\n    wire match = (phase == 1'b0) ? (current_color == weight_group) : (current_color == ~weight_group);\n    wire increment_flag = (phase == 1'b0 && weight_group == 1'b1) || (phase == 1'b1 && weight_group == 1'b0);\n    \n    // Union-find function with limited path compression\n    function [2:0] find;\n        input [2:0] node;\n        begin\n            find = node;\n            if (parent[find] != find) find = parent[find];\n            if (parent[find] != find) find = parent[find];\n            if (parent[find] != find) find = parent[find];\n            if (parent[find] != find) find = parent[find];\n        end\n    endfunction\n    \n    wire [2:0] find_src = find(current_src);\n    wire [2:0] find_dst = find(current_dst);\n    wire should_union = match && (find_src != find_dst);\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 1'b0;\n            min_blue <= 3'd0;\n            max_blue <= 3'd0;\n            current_blue <= 3'd0;\n            phase <= 1'b0;\n            edge_idx <= 5'd0;\n            weight_group <= 1'b0;\n            \n            // Initialize parent array\n            begin : init_parent\n                integer i;\n                for (i = 0; i < N; i = i + 1) begin\n                    parent[i] <= 3'd0;\n                end\n            end\n            \n            // Initialize storage arrays\n            begin : init_arrays\n                integer j;\n                for (j = 0; j < M; j = j + 1) begin\n                    color_reg[j] <= 1'b0;\n                    src_reg[j] <= 3'd0;\n                    dst_reg[j] <= 3'd0;\n                end\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= LOAD;\n                    end\n                end\n                \n                LOAD: begin\n                    // Load edges into registers\n                    begin : load_edges\n                        integer i;\n                        for (i = 0; i < M; i = i + 1) begin\n                            color_reg[i] <= edge[i][6];\n                            src_reg[i] <= edge[i][5:3];\n                            dst_reg[i] <= edge[i][2:0];\n                        end\n                    end\n                    min_blue <= 3'd0;\n                    max_blue <= 3'd0;\n                    phase <= 1'b0;\n                    state <= RESET_PARENT;\n                end\n                \n                RESET_PARENT: begin\n                    // Reset parent array\n                    begin : reset_parents\n                        integer i;\n                        for (i = 0; i < N; i = i + 1) begin\n                            parent[i] <= i[2:0];\n                        end\n                    end\n                    current_blue <= 3'd0;\n                    edge_idx <= 5'd0;\n                    weight_group <= 1'b0;\n                    state <= PROCESS;\n                end\n                \n                PROCESS: begin\n                    if (should_union) begin\n                        parent[find_src] <= find_dst;\n                        if (increment_flag) begin\n                            current_blue <= current_blue + 3'd1;\n                        end\n                    end\n                    \n                    if (edge_idx == 5'd31) begin\n                        state <= NEXT_PASS;\n                        edge_idx <= 5'd0;\n                    end else begin\n                        edge_idx <= edge_idx + 5'd1;\n                    end\n                end\n                \n                NEXT_PASS: begin\n                    if (weight_group == 1'b0) begin\n                        weight_group <= 1'b1;\n                        state <= PROCESS;\n                    end else begin\n                        if (phase == 1'b0) begin\n                            min_blue <= current_blue;\n                            phase <= 1'b1;\n                            state <= RESET_PARENT;\n                        end else begin\n                            max_blue <= current_blue;\n                            state <= CHECK;\n                        end\n                    end\n                end\n                \n                CHECK: begin\n                    result <= (k >= min_blue && k <= max_blue) ? 1'b1 : 1'b0;\n                    done <= 1'b1;\n                    state <= DONE_STATE;\n                end\n                \n                DONE_STATE: begin\n                    done <= 1'b0;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule